import { createAgent, createMiddleware } from 'langchain';
import { z } from 'zod';
import { ChatOpenAI } from '@langchain/openai';

const UserState = z.object({ userName: z.string() });

const userStateMiddleware = createMiddleware({
  name: 'UserState',
  stateSchema: UserState,
  beforeModel: (state) => {
    // Access state.userName in model pre-processing
    console.log('User:', state.userName);
  },
});

const agent = createAgent({
  model: new ChatOpenAI({ model: 'gpt-4o' }),
  tools: [],
  middleware: [userStateMiddleware],
});

await agent.invoke({
  messages: [{ role: 'user', content: 'Hello' }],
  userName: 'Alice',
});
